abstract class system_settings_key_e {
  /// < (string) The file path of the current ringtone
  static const int SYSTEM_SETTINGS_KEY_INCOMING_CALL_RINGTONE = 0;

  /// < (string) The file path of the current home screen wallpaper
  static const int SYSTEM_SETTINGS_KEY_WALLPAPER_HOME_SCREEN = 1;

  /// < (string) The file path of the current lock screen wallpaper
  static const int SYSTEM_SETTINGS_KEY_WALLPAPER_LOCK_SCREEN = 2;

  /// < (int) The current system font size
  static const int SYSTEM_SETTINGS_KEY_FONT_SIZE = 3;

  /// < (string) The current system font type
  static const int SYSTEM_SETTINGS_KEY_FONT_TYPE = 4;

  /// < (bool) Indicates whether the motion service is activated
  static const int SYSTEM_SETTINGS_KEY_MOTION_ACTIVATION = 5;

  /// < (string) The file path of the current email alert ringtone
  static const int SYSTEM_SETTINGS_KEY_EMAIL_ALERT_RINGTONE = 6;

  /// < (bool) Indicates whether the USB debugging is enabled (Since @if MOBILE 2.4 @elseif WEARABLE 3.0 @endif)
  static const int SYSTEM_SETTINGS_KEY_USB_DEBUGGING_ENABLED = 7;

  /// < (bool) Indicates whether the 3G data network is enabled (Since @if MOBILE 2.4 @elseif WEARABLE 3.0 @endif)
  static const int SYSTEM_SETTINGS_KEY_3G_DATA_NETWORK_ENABLED = 8;

  /// < (string) Indicates lockscreen app pkg name
  static const int SYSTEM_SETTINGS_KEY_LOCKSCREEN_APP = 10;

  /// < (string) The current system default font type (only support Get)
  static const int SYSTEM_SETTINGS_KEY_DEFAULT_FONT_TYPE = 11;

  /// < (string) Indicates the current country setting in the <LANGUAGE>_<REGION> syntax. The country setting is in the ISO 639-2 format, and the region setting is in the ISO 3166-1 alpha-2 format
  static const int SYSTEM_SETTINGS_KEY_LOCALE_COUNTRY = 12;

  /// < (string) Indicates the current language setting in the <LANGUAGE>_<REGION> syntax. The language setting is in the ISO 639-2 format and the region setting is in the ISO 3166-1 alpha-2 format.
  static const int SYSTEM_SETTINGS_KEY_LOCALE_LANGUAGE = 13;

  /// < (bool) Indicates whether the 24-hour clock is used. If the value is `false`, the 12-hour clock is used.
  static const int SYSTEM_SETTINGS_KEY_LOCALE_TIMEFORMAT_24HOUR = 14;

  /// < (string) Indicates the current time zone.
  static const int SYSTEM_SETTINGS_KEY_LOCALE_TIMEZONE = 15;

  /// < (int) Once System changes time, this event occurs to notify time change.
  static const int SYSTEM_SETTINGS_KEY_TIME_CHANGED = 16;

  /// < GET (bool) Indicates whether the screen lock sound is enabled on the device. ex) LCD on/off sound
  static const int SYSTEM_SETTINGS_KEY_SOUND_LOCK = 17;

  /// < GET (bool) Indicates whether the device is in the silent mode.
  static const int SYSTEM_SETTINGS_KEY_SOUND_SILENT_MODE = 18;

  /// < GET (bool) Indicates whether the screen touch sound is enabled on the device.
  static const int SYSTEM_SETTINGS_KEY_SOUND_TOUCH = 19;

  /// < GET (bool) Indicates whether rotation control is automatic.
  static const int SYSTEM_SETTINGS_KEY_DISPLAY_SCREEN_ROTATION_AUTO = 20;

  /// < GET (string) Indicates device name.
  static const int SYSTEM_SETTINGS_KEY_DEVICE_NAME = 21;

  /// < GET (bool) Indicates whether the device user has enabled the motion feature.
  static const int SYSTEM_SETTINGS_KEY_MOTION_ENABLED = 22;

  /// < GET (bool) Indicates whether Wi-Fi-related notifications are enabled on the device.
  static const int SYSTEM_SETTINGS_KEY_NETWORK_WIFI_NOTIFICATION = 23;

  /// < GET (bool) Indicates whether the device is in the flight mode.
  static const int SYSTEM_SETTINGS_KEY_NETWORK_FLIGHT_MODE = 24;

  /// < (int) Indicates the backlight time (in seconds). @internal The following values can be used: 15, 30, 60, 120, 300, and 600.
  static const int SYSTEM_SETTINGS_KEY_SCREEN_BACKLIGHT_TIME = 25;

  /// < (string) Indicates the file path of the current notification tone set by the user.
  static const int SYSTEM_SETTINGS_KEY_SOUND_NOTIFICATION = 26;

  /// < (int) Indicates the time period for notification repetitions.
  static const int SYSTEM_SETTINGS_KEY_SOUND_NOTIFICATION_REPETITION_PERIOD =
      27;

  /// < (int) Indicates the current lock state
  static const int SYSTEM_SETTINGS_KEY_LOCK_STATE = 28;

  /// < (string) Indicates Ads ID for each device (Since 3.0)
  static const int SYSTEM_SETTINGS_KEY_ADS_ID = 29;

  /// < (int) Indicates Ultra Data Save status, one of #system_settings_uds_state_e values (Since 4.0)
  static const int SYSTEM_SETTINGS_KEY_ULTRA_DATA_SAVE = 30;

  /// < (string) Indicates Ultra Data Save Package List (Since 4.0), the list is a string containing whitelisted package names separated with semicolons (;)
  static const int SYSTEM_SETTINGS_KEY_ULTRA_DATA_SAVE_PKG_LIST = 31;

  /// < GET (bool) Indicates whether the accessibility TTS is enabled on the device. (Since 4.0)
  static const int SYSTEM_SETTINGS_KEY_ACCESSIBILITY_TTS = 32;

  /// < (bool) Indicates whether vibration is enabled on the device. (Since 4.0)
  static const int SYSTEM_SETTINGS_KEY_VIBRATION = 33;

  /// < (bool) Indicates whether updating time automatically is enabled on the device. (Since 5.0)
  static const int SYSTEM_SETTINGS_KEY_AUTOMATIC_TIME_UPDATE = 34;

  /// < (bool) Indicates whether developer option state is enabled on the device. (Since 5.0)
  static const int SYSTEM_SETTINGS_KEY_DEVELOPER_OPTION_STATE = 35;

  /// < (bool) Indicates whether accessibility grayscale is enabled on the device. (Since 5.5)
  static const int SYSTEM_SETTINGS_KEY_ACCESSIBILITY_GRAYSCALE = 36;

  /// < (bool) Indicates whether accessibility negative color is enabled on the device. (Since 5.5)
  static const int SYSTEM_SETTINGS_KEY_ACCESSIBILITY_NEGATIVE_COLOR = 37;

  /// < (bool) Indicates whether rotary event is enabled on the device. (Since 5.5)
  static const int SYSTEM_SETTINGS_KEY_ROTARY_EVENT_ENABLED = 38;
  static const int SYSTEM_SETTINGS_KEY_MAX = 39;
}

/// Enumeration for Idle Lock State.
///
/// **Since Tizen:**
/// - 2.3.1
/// @nodoc
abstract class system_settings_idle_lock_state_e {
  /// < Device is unlocked
  static const int SYSTEM_SETTINGS_LOCK_STATE_UNLOCK = 0;

  /// < Device is locked
  static const int SYSTEM_SETTINGS_LOCK_STATE_LOCK = 1;

  /// < Device is being locked
  static const int SYSTEM_SETTINGS_LOCK_STATE_LAUNCHING_LOCK = 2;
}

/// Enumeration for font size.
///
/// **Since Tizen:**
/// - 2.3
/// @nodoc
abstract class system_settings_font_size_e {
  /// < A small size
  static const int SYSTEM_SETTINGS_FONT_SIZE_SMALL = 0;

  /// < A normal size
  static const int SYSTEM_SETTINGS_FONT_SIZE_NORMAL = 1;

  /// < A large size
  static const int SYSTEM_SETTINGS_FONT_SIZE_LARGE = 2;

  /// < A huge size
  static const int SYSTEM_SETTINGS_FONT_SIZE_HUGE = 3;

  /// < A giant size
  static const int SYSTEM_SETTINGS_FONT_SIZE_GIANT = 4;
}

/// Enumeration for Ultra Data Save.
///
/// **Since Tizen:**
/// - 4.0
/// @nodoc
abstract class system_settings_uds_state_e {
  /// < OFF
  static const int SYSTEM_SETTINGS_UDS_OFF = 0;

  /// < ON
  static const int SYSTEM_SETTINGS_UDS_ON = 1;

  /// < UDS on and the app is whitelisted
  static const int SYSTEM_SETTINGS_UDS_ON_WHITELISTED = 2;
}

/// Called when the system settings changes.
///
/// **Since Tizen:**
/// - 2.3
///
/// **Parameters:**
/// - `key` (in): The key name of the system settings changed system settings
/// - `user_data` (in): The user data passed from the callback registration function
///
/// **Preconditions:**
/// - system_settings_set_changed_cb() will invoke this callback function.
///
/// **See also:**
/// - `system_settings_set_changed_cb()`
/// - `system_settings_unset_changed_cb()`
/// @nodoc
typedef system_settings_changed_cb
    = ffi.Pointer<ffi.NativeFunction<system_settings_changed_cbFunction>>;
/// @nodoc
typedef system_settings_changed_cbFunction = ffi.Void Function(
    ffi.Int32 key, ffi.Pointer<ffi.Void> user_data);
/// @nodoc
typedef Dartsystem_settings_changed_cbFunction = void Function(
    int key, ffi.Pointer<ffi.Void> user_data);

/// Called to get each string value from string typed list.
///
/// **Since Tizen:**
/// - 3.0
///
/// **Parameters:**
/// - `index` (in): zero based number indicating index of node in a list
/// - `value` (in): value returned from the list
/// - `cb_data` (in): The user data passed from the foreach function
///
/// **Returns:**
/// - `true` to continue with the next iteration of the loop, otherwise false to break out of the loop
///
/// **Platform:**
/// - Platform API.
/// @nodoc
typedef system_settings_iter_cb
    = ffi.Pointer<ffi.NativeFunction<system_settings_iter_cbFunction>>;
/// @nodoc
typedef system_settings_iter_cbFunction = ffi.Bool Function(
    ffi.Int index, ffi.Pointer<ffi.Char> value, ffi.Pointer<ffi.Void> cb_data);
/// @nodoc
typedef Dartsystem_settings_iter_cbFunction = bool Function(
    int index, ffi.Pointer<ffi.Char> value, ffi.Pointer<ffi.Void> cb_data);
